const DB='patrimoine-simple-db',VER=5,APP_VERSION='5.2.0';let db,deferredPrompt,pendingImport=null;let state={view:'dashboard',positions:[],assetTransactions:[],contributions:[],assets:[],platforms:[],snapshots:[],selectedContributionYear:null,selectedContributionDetailYear:null,marketBusy:false,marketMessage:'',settings:{usdToEur:.8474576271,autoMarketUpdate:true}};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const eur=new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:2}),num=new Intl.NumberFormat('fr-FR',{maximumFractionDigits:8}),dateFmt=new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium'});
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
