function marketConfig(p){const symbol=String(p.symbol||'').toUpperCase().trim(),preset=MARKET_ASSETS[symbol];if(p.marketId){return p.category==='Crypto'?{provider:'coingecko',id:String(p.marketId).trim(),label:p.symbol}:{provider:'yahoo',symbol:String(p.marketId).trim(),label:p.symbol}}return preset}
const MARKET_TIMEOUT=6500;
function withTimeout(promise,ms=MARKET_TIMEOUT){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),ms);return {signal:controller.signal,done:promise(controller.signal).finally(()=>clearTimeout(timer))}}
async function fetchJSON(url){const x=withTimeout(signal=>fetch(url,{cache:'no-store',headers:{Accept:'application/json'},signal}));const r=await x.done;if(!r.ok)throw new Error(`HTTP ${r.status}`);return r.json()}
async function fetchJSONAny(url){const candidates=[url,`https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`,`https://corsproxy.io/?url=${encodeURIComponent(url)}`];let last;for(const candidate of candidates){try{const x=withTimeout(signal=>fetch(candidate,{cache:'no-store',headers:{Accept:'application/json'},signal}));const r=await x.done;if(!r.ok)throw new Error(`HTTP ${r.status}`);const text=await r.text();if(/^\s*</.test(text))throw new Error('Réponse HTML inattendue');const data=JSON.parse(text);return data}catch(e){last=e}}throw last||new Error('Données indisponibles')}
async function fetchText(url){const candidates=[url,`https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`,`https://corsproxy.io/?url=${encodeURIComponent(url)}`];let last;for(const candidate of candidates){try{const x=withTimeout(signal=>fetch(candidate,{cache:'no-store',signal}));const r=await x.done;if(!r.ok)throw new Error(`HTTP ${r.status}`);const text=await r.text();if(text&& !/^\s*</.test(text))return text;last=new Error('Réponse de marché invalide')}catch(e){last=e}}throw last||new Error('Cours indisponible')}
function parseStooqClose(csv){const lines=csv.trim().split(/\r?\n/).filter(Boolean);if(lines.length<2)throw new Error('Cotations ETF indisponibles');const headers=lines[0].split(',').map(x=>x.trim().toLowerCase()),vals=lines[1].split(',').map(x=>x.trim());const i=headers.indexOf('close'),value=Number((vals[i]||'').replace(',','.'));if(!Number.isFinite(value)||value<=0)throw new Error('Cours ETF invalide');return value}
async function getStooqPrice(symbol){return parseStooqClose(await fetchText(`https://stooq.com/q/l/?s=${encodeURIComponent(symbol)}&f=sd2t2ohlcv&h&e=csv`))}
function parseYahooPrice(data){const result=data?.chart?.result?.[0];if(!result)throw new Error(data?.chart?.error?.description||'Cours Yahoo indisponible');const direct=Number(result.meta?.regularMarketPrice);if(Number.isFinite(direct)&&direct>0)return direct;const closes=result.indicators?.quote?.[0]?.close||[];for(let i=closes.length-1;i>=0;i--){const value=Number(closes[i]);if(Number.isFinite(value)&&value>0)return value}throw new Error('Cours Yahoo invalide')}
async function getYahooPrice(symbol,fallback){let last;for(const host of ['query1.finance.yahoo.com','query2.finance.yahoo.com']){try{return parseYahooPrice(await fetchJSONAny(`https://${host}/v8/finance/chart/${encodeURIComponent(symbol)}?interval=1d&range=5d`))}catch(e){last=e}}if(fallback){try{return await getStooqPrice(fallback)}catch(e){last=e}}throw last||new Error('Cours ETF indisponible')}
function marketDateLabel(value=state.settings.lastMarketUpdate){return dateTimeLabel(value,'Jamais')}
function marketDisplayState(){const errors=Array.isArray(state.settings.lastMarketErrors)?state.settings.lastMarketErrors:[],last=state.settings.lastMarketUpdate?new Date(state.settings.lastMarketUpdate):null,age=last&&!Number.isNaN(last.getTime())?Date.now()-last.getTime():Infinity;if(state.marketBusy)return {className:'updating',icon:'refresh',title:'Actualisation des cours…',detail:'Les dernières valeurs valides restent affichées.'};if(!navigator.onLine)return {className:'offline',icon:'offline',title:'Hors ligne',detail:`Dernière mise à jour ${marketDateLabel()}`};if(!last||age>24*60*60*1000)return {className:'stale',icon:'warning',title:'Actualisation recommandée',detail:last?`Dernière mise à jour ${marketDateLabel()}`:'Aucune mise à jour enregistrée'};if(errors.length)return {className:'partial',icon:'warning',title:'Actualisation partiellement réussie',detail:`${errors.length} cours indisponible${errors.length>1?'s':''} · dernières valeurs conservées`};return {className:'current',icon:'check',title:'Cours actualisés',detail:`Dernière mise à jour ${marketDateLabel()}`}}
function providerSummaries(){const statuses=Array.isArray(state.settings.lastMarketStatus)?state.settings.lastMarketStatus:[],cryptoLabels=new Set(state.positions.filter(p=>marketConfig(p)?.provider==='coingecko').map(p=>p.symbol)),marketLabels=new Set(state.positions.filter(p=>marketConfig(p)?.provider==='yahoo').map(p=>(marketConfig(p).label||p.symbol))),groups=[{name:'CoinGecko',type:'Cryptomonnaies et stablecoins',match:x=>cryptoLabels.has(x.label)},{name:'Yahoo Finance / Stooq',type:'ETF et actions · secours Stooq',match:x=>marketLabels.has(x.label)},{name:'Frankfurter',type:'Taux USD/EUR',match:x=>x.label==='USD/EUR'}];return groups.map(g=>{const rows=statuses.filter(g.match),stateLabel=!rows.length?'Non vérifié':rows.every(x=>x.ok)?'Actualisé':rows.some(x=>x.ok)?'Partiel':'Indisponible',error=rows.find(x=>!x.ok&&x.detail)?.detail;return {...g,state:stateLabel,tone:!rows.length?'neutral':rows.every(x=>x.ok)?'ok':'ko',detail:!rows.length?'Aucun contrôle enregistré':stateLabel==='Actualisé'?`Dernière réussite ${marketDateLabel()}`:error||'Dernières valeurs valides conservées'}})}
async function updateMarketPrices({silent=false}={}){
  if(state.marketBusy)return;state.marketBusy=true;state.marketMessage='Actualisation…';render();
  const updates={},errors=[],statuses=[],status=(label,ok,detail='')=>statuses.push({label,ok,detail});
  const crypto=state.positions.filter(p=>marketConfig(p)?.provider==='coingecko'),stocks=state.positions.filter(p=>marketConfig(p)?.provider==='yahoo');
  try{
    const cryptoTask=async()=>{const ids=[...new Set(crypto.map(p=>marketConfig(p).id))];if(!ids.length)return;try{const data=await fetchJSON(`https://api.coingecko.com/api/v3/simple/price?ids=${encodeURIComponent(ids.join(','))}&vs_currencies=usd`);for(const p of crypto){const price=Number(data?.[marketConfig(p).id]?.usd);if(Number.isFinite(price)&&price>0){updates[p.id]=price;status(p.symbol,true)}else{errors.push(p.symbol);status(p.symbol,false,'Cours absent')}}}catch(e){for(const p of crypto){errors.push(p.symbol);status(p.symbol,false,e.message)}}};
    const fxTask=async()=>{try{const fx=await fetchJSON('https://api.frankfurter.dev/v1/latest?base=USD&symbols=EUR'),rate=Number(fx?.rates?.EUR);if(!Number.isFinite(rate)||rate<=0)throw new Error('Taux invalide');await put('settings',{key:'usdToEur',value:rate});state.settings.usdToEur=rate;status('USD/EUR',true)}catch(e){errors.push('USD/EUR');status('USD/EUR',false,e.message)}};
    const stockTask=async p=>{const cfg=marketConfig(p);try{updates[p.id]=await getYahooPrice(cfg.symbol,cfg.fallback);status(cfg.label||p.symbol,true,cfg.symbol)}catch(e){errors.push(cfg.label||p.symbol);status(cfg.label||p.symbol,false,e.message)}};
    await Promise.all([cryptoTask(),fxTask(),...stocks.map(stockTask)]);
    for(const [id,price] of Object.entries(updates)){const pos=state.positions.find(p=>p.id===id);if(pos){pos.currentPrice=price;await put('positions',pos)}}
    const stamp=new Date().toISOString(),uniqueErrors=[...new Set(errors)];await put('settings',{key:'lastMarketUpdate',value:stamp});await put('settings',{key:'lastMarketErrors',value:uniqueErrors});await put('settings',{key:'lastMarketStatus',value:statuses});state.settings.lastMarketUpdate=stamp;state.settings.lastMarketErrors=uniqueErrors;state.settings.lastMarketStatus=statuses;
    state.marketMessage=uniqueErrors.length?`Mise à jour partielle : ${uniqueErrors.join(', ')}`:`${Object.keys(updates).length} cours et le change actualisés`;
    if(!silent)showToast(uniqueErrors.length?'Actualisation partiellement réussie':'Cours actualisés',uniqueErrors.length?'warning':'success');
  }catch(e){state.marketMessage='Actualisation impossible';if(!silent)alert(`Impossible d’actualiser les cours : ${e.message}`)}finally{state.marketBusy=false;await load()}
}

function inferredAssetType(p){const symbol=String(p.symbol||'').toUpperCase().trim(),name=String(p.name||'').toLowerCase(),category=String(p.category||'');if(p.assetType)return p.assetType;if(STABLECOINS.has(symbol)||/(stablecoin|usd coin|tether|dai)/i.test(name))return 'stablecoin';if(category==='Liquidités'||/(espèces|especes|cash|liquidit)/i.test(name)||/^(EUR|USD|CASH)(-|$)/.test(symbol))return 'cash';return 'investment'}
function normalizedPosition(p){const assetType=inferredAssetType(p);return {...p,assetType,category:p.category==='Liquidités'?'Bourse':p.category}}
function isLiquidity(p){return inferredAssetType(p)!=='investment'};
function openDB(){return new Promise((res,rej)=>{const r=indexedDB.open(DB,VER);r.onupgradeneeded=()=>{for(const [n,k] of [['positions','id'],['assetTransactions','id'],['contributions','id'],['assets','id'],['platforms','id'],['settings','key'],['snapshots','date']])if(!r.result.objectStoreNames.contains(n))r.result.createObjectStore(n,{keyPath:k})};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function req(s,m,a){return new Promise((res,rej)=>{const r=a(db.transaction(s,m).objectStore(s));r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}const all=s=>req(s,'readonly',o=>o.getAll()),put=(s,v)=>req(s,'readwrite',o=>o.put(v)),del=(s,k)=>req(s,'readwrite',o=>o.delete(k)),clear=s=>req(s,'readwrite',o=>o.clear());
async function fetchSeed(){const r=await fetch('./assets/seed.json?v=40',{cache:'no-store'});if(!r.ok)throw new Error('Données initiales introuvables');return r.json()}
async function seed(force=false){if((await all('positions')).length&&!force)return;for(const s of ['positions','assetTransactions','contributions','assets','platforms','settings','snapshots'])await clear(s);const d=await fetchSeed();for(const x of d.positions)await put('positions',x);for(const x of d.assetTransactions)await put('assetTransactions',x);for(const x of d.contributions)await put('contributions',x);for(const [key,value] of Object.entries(d.settings))await put('settings',{key,value})}
const refKey=s=>String(s||'').trim().toLocaleLowerCase('fr-FR').replace(/\s+/g,' ');
const assetRefId=p=>`asset:${String(p.category||'').toLowerCase()}:${String(p.symbol||'').trim().toUpperCase()}`;
const platformRefId=name=>`platform:${refKey(name).replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'')||'sans-nom'}`;
function assetFromPosition(p){return {id:p.assetId||assetRefId(p),symbol:String(p.symbol||'').trim().toUpperCase(),name:String(p.name||'').trim(),category:p.category==='Liquidités'?'Bourse':p.category,assetType:inferredAssetType(p),currency:p.currency||'EUR',marketId:p.marketId||'',active:true}}
async function ensurePlatform(name){const clean=String(name||'').trim();if(!clean)return '';const existing=(await all('platforms')).find(x=>refKey(x.name)===refKey(clean));if(existing)return existing.id;const x={id:platformRefId(clean),name:clean,active:true};await put('platforms',x);return x.id}
async function migrate(){const d=await fetchSeed(),existing=await all('positions'),pids=new Set(existing.map(x=>x.id)),cids=new Set((await all('contributions')).map(x=>x.id));for(const p of d.positions)if(!pids.has(p.id))await put('positions',normalizedPosition(p));for(const p of await all('positions')){const n=normalizedPosition(p),candidate=assetFromPosition(n),canonical=(await all('assets')).find(x=>x.id===candidate.id)||candidate;if(!(await all('assets')).some(x=>x.id===canonical.id))await put('assets',canonical);const platformId=await ensurePlatform(n.account),platform=(await all('platforms')).find(x=>x.id===platformId);await put('positions',{...n,assetId:canonical.id,platformId,symbol:canonical.symbol,name:canonical.name,category:canonical.category,currency:canonical.currency,marketId:canonical.marketId||'',account:platform?.name||n.account})}for(const c of d.contributions)if(!cids.has(c.id))await put('contributions',c);for(const c of await all('contributions')){const platformId=await ensurePlatform(c.destination);if(c.platformId!==platformId)await put('contributions',{...c,platformId,destination:(await all('platforms')).find(x=>x.id===platformId)?.name||c.destination})}const settings=Object.fromEntries((await all('settings')).map(x=>[x.key,x.value]));if(settings.autoMarketUpdate===undefined)await put('settings',{key:'autoMarketUpdate',value:true});await put('settings',{key:'appVersion',value:APP_VERSION})}
const normalizedPlatformLabel=name=>String(name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase();
function canonicalPlatformName(name){const key=normalizedPlatformLabel(name);if(key.startsWith('bourse direct'))return 'Bourse Direct';if(key.startsWith('meria'))return 'Méria';return String(name||'').trim()}
async function cleanupPlatformReferences(){const platforms=await all('platforms');for(const p of await all('positions')){const source=platforms.find(x=>x.id===p.platformId)?.name||p.account||'',name=canonicalPlatformName(source);if(!name)continue;const id=await ensurePlatform(name),target=(await all('platforms')).find(x=>x.id===id);if(p.platformId!==id||p.account!==target?.name)await put('positions',{...p,platformId:id,account:target?.name||name})}for(const c of await all('contributions')){const source=platforms.find(x=>x.id===c.platformId)?.name||c.destination||'',name=canonicalPlatformName(source);if(!name)continue;const id=await ensurePlatform(name),target=(await all('platforms')).find(x=>x.id===id);if(c.platformId!==id||c.destination!==target?.name)await put('contributions',{...c,platformId:id,destination:target?.name||name})}for(const platform of await all('platforms')){const canonical=canonicalPlatformName(platform.name);if(canonical!==platform.name&&['Bourse Direct','Méria'].includes(canonical))await del('platforms',platform.id)}}
async function ensureCryptoLibrary(){const existing=new Set((await all('assets')).map(a=>a.id));for(const [symbol,name,marketId] of CRYPTO_LIBRARY){const id=assetRefId({category:'Crypto',symbol});if(!existing.has(id))await put('assets',{id,symbol,name,category:'Crypto',assetType:STABLECOINS.has(symbol)?'stablecoin':'investment',currency:'USD',marketId,active:true})}}
async function load(){await cleanupPlatformReferences();await ensureCryptoLibrary();state.positions=await all('positions');state.assetTransactions=await all('assetTransactions');state.contributions=await all('contributions');state.assets=await all('assets');state.platforms=await all('platforms');state.settings=Object.fromEntries((await all('settings')).map(x=>[x.key,x.value]));state.snapshots=await all('snapshots');render()}
function livePositions(){return state.positions.map(p=>{let quantity=+p.quantity,cost=Number.isFinite(+p.costBasis)?+p.costBasis:quantity*(+p.averageCost);for(const t of state.assetTransactions.filter(t=>t.positionId===p.id).sort((a,b)=>a.date.localeCompare(b.date))){const q=+t.quantity,price=+t.unitPrice,fees=+t.fees||0;if(t.type==='BUY'){quantity+=q;cost+=q*price+fees}else if(t.type==='SELL'){const avg=quantity?cost/quantity:0;quantity-=q;cost=Math.max(0,cost-avg*q)}else if(t.type==='REWARD'||t.type==='ADJUSTMENT')quantity+=q}const averageCost=quantity?cost/quantity:0,value=quantity*(+p.currentPrice),gain=value-cost,perf=cost?gain/cost*100:0;return {...normalizedPosition(p),quantity,cost,averageCost,value,gain,perf}})}
const toEUR=(v,c)=>c==='USD'?v*(+state.settings.usdToEur||0):v;
function portfolioBreakdown(){const ps=livePositions(),crypto=ps.filter(p=>p.category==='Crypto'),bourse=ps.filter(p=>p.category!=='Crypto');return {ps,crypto,bourse,cryptoUSD:crypto.reduce((s,p)=>s+p.value,0),bourseEUR:bourse.reduce((s,p)=>s+toEUR(p.value,p.currency),0)}}
function contributionTotals(){const crypto=state.contributions.filter(c=>c.domain==='Crypto').reduce((s,c)=>s+(+c.amount),0),bourse=state.contributions.filter(c=>c.domain==='Bourse').reduce((s,c)=>s+(+c.amount),0);return {crypto,bourse,total:crypto+bourse}}
function metrics(){const p=portfolioBreakdown(),i=contributionTotals(),rate=+state.settings.usdToEur||0,cryptoEUR=p.cryptoUSD*rate,total=cryptoEUR+p.bourseEUR,gain=total-i.total,perf=i.total?gain/i.total*100:0,cryptoGain=cryptoEUR-i.crypto,cryptoGainUSD=rate?cryptoGain/rate:0,bourseGain=p.bourseEUR-i.bourse;return {...p,...i,rate,cryptoEUR,total,gain,perf,cryptoGain,cryptoGainUSD,bourseGain}}
function annual(){const m={};for(const c of state.contributions){const y=c.date.slice(0,4);m[y]??={Crypto:0,Bourse:0};m[y][c.domain]=(m[y][c.domain]||0)+(+c.amount)}return Object.entries(m).sort((a,b)=>b[0].localeCompare(a[0]))}
const unitQuote=p=>`Cours : ${money(p.currentPrice,p.currency)}`;
function rowForAsset(p){return `<button class="list-row asset-open" data-position="${p.id}"><span class="row-icon">${esc(p.symbol.slice(0,4))}</span><span class="row-main"><strong>${esc(p.name)}</strong><span>${esc(p.account)} · ${num.format(p.quantity)} ${esc(p.symbol)}</span><span>${unitQuote(p)}</span></span><span class="row-value"><strong>${money(p.value,p.currency)}</strong><span class="${tone(p.gain)}">${pct(p.perf)}</span></span><span class="chevron">${icon('chevron')}</span></button>`}
function dashboard(){const m=metrics(),cryptoPerf=m.crypto?m.cryptoGain/m.crypto*100:0,boursePerf=m.bourse?m.bourseGain/m.bourse*100:0,market=marketDisplayState();return `<section class="section"><span class="section-label">Patrimoine actuel</span><article class="card hero-card"><div class="hero-label">Valeur totale estimée</div><div class="hero-value">${eur.format(m.total)}</div><div class="performance-line ${tone(m.gain)}"><span>${m.gain>=0?'▲':'▼'}</span><span>${m.gain>=0?'+':''}${eur.format(m.gain)}</span><span>${pct(m.perf)}</span></div><div class="hero-meta hero-meta-single"><div><span class="meta-label">Apports cumulés</span><span class="meta-value">${eur.format(m.crypto+m.bourse)}</span></div></div><div class="portfolio-meter"><span style="width:${Math.min(100,Math.max(0,m.total/(m.crypto+m.bourse||1)*100))}%"></span></div></article><div class="status-row ${market.className}"><span class="status-dot"></span><span class="status-copy"><strong>${market.title}</strong><span>${market.detail}</span></span></div></section>
<section class="section"><span class="section-label">Répartition</span><div class="split-summary"><article class="card summary-card"><span class="section-label">Crypto</span><div class="summary-value">${eur.format(m.cryptoEUR)}</div><div class="summary-currency">${money(m.cryptoUSD,'USD')}</div><div class="summary-performance ${tone(m.cryptoGain)}"><span>${m.cryptoGain>=0?'▲':'▼'}</span><span>${m.cryptoGainUSD>=0?'+':''}${money(m.cryptoGainUSD,'USD')}</span><span>${m.cryptoGain>=0?'+':''}${eur.format(m.cryptoGain)}</span><span>${pct(cryptoPerf)}</span></div><div class="progress"><span style="width:${m.total?Math.max(0,Math.min(100,m.cryptoEUR/m.total*100)):0}%"></span></div></article><article class="card summary-card"><span class="section-label">Bourse</span><div class="summary-value">${eur.format(m.bourseEUR)}</div><div class="summary-performance ${tone(m.bourseGain)}"><span>${m.bourseGain>=0?'▲':'▼'}</span><span>${m.bourseGain>=0?'+':''}${eur.format(m.bourseGain)}</span><span>${pct(boursePerf)}</span></div><div class="progress"><span style="width:${m.total?Math.max(0,Math.min(100,m.bourseEUR/m.total*100)):0}%"></span></div></article></div></section>
<section class="section"><div class="section-title-row"><div><span class="section-label">Positions</span><h2>Actifs</h2></div><button class="text-button" data-go="portfolio">Tout afficher</button></div><div class="group-card">${m.ps.slice(0,5).map(rowForAsset).join('')}</div></section>
<section class="section"><div class="section-title-row"><div><span class="section-label">Apports</span><h2>Investissements</h2></div><button class="text-button" data-go="contributions">Voir les apports</button></div><div class="group-card"><div class="list-row"><span class="row-icon">₿</span><span class="row-main"><strong>Crypto</strong><span>Total net investi</span></span><span class="row-value"><strong>${eur.format(m.crypto)}</strong></span></div><div class="list-row"><span class="row-icon">€</span><span class="row-main"><strong>Bourse</strong><span>Total net investi</span></span><span class="row-value"><strong>${eur.format(m.bourse)}</strong></span></div></div></section>`}
function positionCard(p){const ratio=p.cost?Math.max(0,Math.min(100,p.value/p.cost*100)):0,arrow=p.gain>=0?'▲':'▼';return `<button class="card position-card asset-open" data-position="${p.id}"><div class="position-head"><span class="row-icon">${esc(p.symbol.slice(0,4))}</span><span class="position-name"><strong>${esc(p.name)}</strong><span>${esc(p.account)} · ${num.format(p.quantity)} ${esc(p.symbol)}</span><span>${unitQuote(p)}</span></span><span class="chevron">${icon('chevron')}</span></div><div class="position-value">${money(p.value,p.currency)}</div><div class="position-performance ${tone(p.gain)}"><span>${arrow}</span><span>${p.gain>=0?'+':''}${money(p.gain,p.currency)}</span><span>${pct(p.perf)}</span></div><div class="position-meter"><span class="${tone(p.gain)}" style="width:${ratio}%"></span></div></button>`}
function liquidityCard(p){return `<button class="card position-card liquidity-card asset-open" data-position="${p.id}"><div class="position-head"><span class="row-icon liquidity-icon">${esc(p.symbol.slice(0,4))}</span><span class="position-name"><strong>${esc(p.name)}</strong><span>${esc(p.account)} · ${num.format(p.quantity)} ${esc(p.symbol)}</span><span>${unitQuote(p)}</span></span><span class="chevron">${icon('chevron')}</span></div><div class="position-value">${money(p.value,p.currency)}</div></button>`}
function portfolioSection(label,title,description,items,renderer=positionCard){if(!items.length)return '';return `<section class="section"><div class="section-title-row"><div><span class="section-label">${label}</span><h2>${title}</h2><p>${description}</p></div></div><div class="position-grid">${items.map(renderer).join('')}</div></section>`}
function portfolio(){const {crypto,bourse}=portfolioBreakdown(),cryptoPositions=crypto.filter(p=>inferredAssetType(p)==='investment'),stablecoins=crypto.filter(p=>inferredAssetType(p)==='stablecoin'),boursePositions=bourse.filter(p=>inferredAssetType(p)==='investment'),cash=bourse.filter(p=>inferredAssetType(p)==='cash');return `${portfolioSection('Positions investies','Crypto','',cryptoPositions)}${portfolioSection('Liquidités Crypto','Stablecoins','',stablecoins,liquidityCard)}${portfolioSection('Positions investies','Bourse','',boursePositions)}${portfolioSection('Liquidités Bourse','Espèces disponibles','',cash,liquidityCard)}<button id="newAssetTx" class="floating-action" aria-label="Nouvelle opération">${icon('plus')}</button>`}
function operations(){const tx=[...state.assetTransactions].sort((a,b)=>b.date.localeCompare(a.date));return `<section class="section"><div class="section-title-row"><div><span class="section-label">Depuis la photographie initiale</span><h2>Historique</h2></div><button class="text-button" id="newAssetTx">Ajouter</button></div><div class="group-card">${tx.map(t=>{const p=state.positions.find(x=>x.id===t.positionId)||{};const label={BUY:'Achat',SELL:'Vente',REWARD:'Récompense',ADJUSTMENT:'Correction'}[t.type];return `<div class="operation-row"><div><strong>${esc(p.symbol)} · ${label}</strong><span>${dateFmt.format(new Date(t.date+'T12:00:00'))}${t.note?' · '+esc(t.note):''}</span></div><div class="operation-amount"><strong>${num.format(t.quantity)}</strong><button class="text-button negative" data-delete-tx="${t.id}">Supprimer</button></div></div>`}).join('')||'<div class="empty">Aucune nouvelle opération.</div>'}</div></section>`}
function annualTable(){return `<div class="card table-wrap"><table class="simple-table"><thead><tr><th>Année</th><th>Crypto</th><th>Bourse</th><th>Total</th></tr></thead><tbody>${annual().map(([y,v])=>`<tr><td><strong>${y}</strong></td><td>${eur.format(v.Crypto||0)}</td><td>${eur.format(v.Bourse||0)}</td><td><strong>${eur.format((v.Crypto||0)+(v.Bourse||0))}</strong></td></tr>`).join('')}</tbody></table></div>`}
function monthLabel(ym){return new Intl.DateTimeFormat('fr-FR',{month:'long',year:'numeric'}).format(new Date(ym+'-01T12:00:00'))}
function shiftMonth(ym,n){const d=new Date(ym+'-01T12:00:00');d.setMonth(d.getMonth()+n);return d.toISOString().slice(0,7)}
function contributionYears(){return [...new Set(state.contributions.map(c=>c.date.slice(0,4)))].sort((a,b)=>b.localeCompare(a))}
function monthly(year){const m={};for(const c of state.contributions){if(c.date.slice(0,4)!==year)continue;const ym=c.date.slice(0,7);m[ym]??={Crypto:0,Bourse:0};m[ym][c.domain]=(m[ym][c.domain]||0)+(+c.amount)}return Object.entries(m).sort((a,b)=>a[0].localeCompare(b[0]))}
function monthlyTable(){const years=contributionYears();if(!state.selectedContributionYear||!years.includes(state.selectedContributionYear))state.selectedContributionYear=years[0]||String(new Date().getFullYear());const rows=monthly(state.selectedContributionYear);return `<div class="year-tabs" role="tablist" aria-label="Année des apports mensuels">${years.map(y=>`<button class="year-tab ${y===state.selectedContributionYear?'active':''}" data-contribution-year="${y}" role="tab" aria-selected="${y===state.selectedContributionYear}">${y}</button>`).join('')}</div><div class="card table-wrap"><table class="simple-table"><thead><tr><th>Mois</th><th>Crypto</th><th>Bourse</th><th>Total</th></tr></thead><tbody>${rows.length?rows.map(([ym,v])=>`<tr><td><strong>${monthLabel(ym)}</strong></td><td>${eur.format(v.Crypto||0)}</td><td>${eur.format(v.Bourse||0)}</td><td><strong>${eur.format((v.Crypto||0)+(v.Bourse||0))}</strong></td></tr>`).join(''):`<tr><td colspan="4" class="empty-table">Aucun apport enregistré en ${state.selectedContributionYear}.</td></tr>`}</tbody></table></div>`}
function contributionDetail(){const years=contributionYears();if(!state.selectedContributionDetailYear||!years.includes(state.selectedContributionDetailYear))state.selectedContributionDetailYear=years[0]||String(new Date().getFullYear());const rows=[...state.contributions].filter(c=>c.date.slice(0,4)===state.selectedContributionDetailYear).sort((a,b)=>b.date.localeCompare(a.date)),total=rows.reduce((sum,c)=>sum+(+c.amount||0),0);return `<div class="detail-year-head"><div class="year-tabs" role="tablist" aria-label="Année des apports enregistrés">${years.map(y=>`<button class="year-tab ${y===state.selectedContributionDetailYear?'active':''}" data-contribution-detail-year="${y}" role="tab" aria-selected="${y===state.selectedContributionDetailYear}">${y}</button>`).join('')}</div><strong class="detail-year-total">${eur.format(total)}</strong></div><div class="group-card">${rows.length?rows.map(c=>`<div class="operation-row"><div><strong>${esc(c.domain)} · ${esc(c.destination)}</strong><span>${dateFmt.format(new Date(c.date+'T12:00:00'))}</span></div><div class="operation-amount"><strong class="${tone(c.amount)}">${eur.format(c.amount)}</strong><div class="row-actions"><button class="text-button" data-edit-contribution="${c.id}">Modifier</button><button class="text-button danger-link" data-delete-contribution="${c.id}">Supprimer</button></div></div></div>`).join(''):`<div class="empty">Aucun apport enregistré en ${state.selectedContributionDetailYear}.</div>`}</div>`}
function contributions(){const i=contributionTotals();return `<section class="section"><span class="section-label">Répartition des apports</span><div class="split-summary"><article class="card summary-card"><span class="section-label">Crypto</span><div class="summary-value">${eur.format(i.crypto)}</div><div class="summary-detail">${i.total?pct(i.crypto/i.total*100):'—'} des apports</div></article><article class="card summary-card"><span class="section-label">Bourse</span><div class="summary-value">${eur.format(i.bourse)}</div><div class="summary-detail">${i.total?pct(i.bourse/i.total*100):'—'} des apports</div></article></div></section><section class="section"><div class="section-title-row"><div><span class="section-label">Historique annuel</span><h2>${eur.format(i.total)}</h2></div></div>${annualTable()}</section><section class="section"><div class="section-title-row"><div><span class="section-label">Historique mensuel</span><h2>Apports par mois</h2></div></div>${monthlyTable()}</section><section class="section"><div class="section-title-row"><div><span class="section-label">Détail</span><h2>Apports enregistrés</h2></div><button id="newContribution" class="text-button">Ajouter</button></div>${contributionDetail()}</section>`}

function backupDateLabel(value=state.settings.lastBackupAt){return dateTimeLabel(value,'Aucune sauvegarde')}
function lastModifiedLabel(){return dateTimeLabel(state.settings.lastModifiedAt,'Non enregistrée')}
function backupIsDue(){if(!state.settings.lastBackupAt)return true;const age=Date.now()-new Date(state.settings.lastBackupAt).getTime();return !Number.isFinite(age)||age>30*24*60*60*1000}
function backupFileName(){const d=new Date(),pad=n=>String(n).padStart(2,'0');return `Patrimoine_${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}_${pad(d.getHours())}-${pad(d.getMinutes())}.json`}
function backupSummary(d){return {date:d.exportedAt||d.createdAt||null,positions:Array.isArray(d.positions)?d.positions.length:0,contributions:Array.isArray(d.contributions)?d.contributions.length:0,operations:Array.isArray(d.assetTransactions)?d.assetTransactions.length:0,version:d.appVersion||d.version||'Inconnue'}}
function validateBackup(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw new Error('Le fichier ne contient pas une sauvegarde valide.');if(raw.app&&raw.app!=='Patrimoine')throw new Error('Cette sauvegarde ne correspond pas à Patrimoine.');if(raw.schemaVersion!=null&&(!Number.isInteger(raw.schemaVersion)||raw.schemaVersion<1))throw new Error('Version de sauvegarde invalide.');const data=raw.data&&typeof raw.data==='object'&&!Array.isArray(raw.data)?raw.data:raw,d={...raw,positions:data.positions,assetTransactions:data.assetTransactions,contributions:data.contributions,assets:data.assets||raw.assets||[],platforms:data.platforms||raw.platforms||[],snapshots:data.snapshots||raw.snapshots||[],settings:raw.settings||data.settings||{}};for(const k of ['positions','assetTransactions','contributions','assets','platforms'])if(!Array.isArray(d[k]))throw new Error(`Données manquantes : ${k}.`);if(!Array.isArray(d.snapshots))throw new Error('Historique invalide.');if(d.settings!=null&&(typeof d.settings!=='object'||Array.isArray(d.settings)))throw new Error('Réglages invalides.');return d}
function settings(){const auto=state.settings.autoMarketUpdate!==false,market=marketDisplayState(),providers=providerSummaries(),providerRows=providers.map(p=>`<div class="market-status ${p.tone}"><span><strong>${esc(p.name)}</strong><span>${esc(p.type)}</span><small class="provider-detail">${esc(p.detail)}</small></span><span class="provider-state">${esc(p.state)}</span></div>`).join('');return `<section class="section"><span class="section-label">Cotations</span><div class="group-card settings-list"><button class="list-row" id="refreshMarkets"><span class="row-icon refresh-icon ${state.marketBusy?'spinning':''}">${icon('refresh')}</span><span class="row-main"><strong>${state.marketBusy?'Actualisation des cours…':'Actualiser les cours'}</strong><span>Crypto, ETF et taux USD/EUR</span></span><span class="chevron">${icon('chevron')}</span></button><label class="settings-row toggle-row"><div class="settings-copy"><strong>Actualisation au démarrage</strong><span>Le dernier cours reste disponible hors connexion</span></div><input id="autoMarketUpdate" type="checkbox" ${auto?'checked':''}></label><div class="settings-row market-update-summary"><div class="settings-copy"><strong class="market-state-line ${market.className==='current'?'positive':market.className==='offline'?'':market.className==='updating'?'': 'warning'}">${icon(market.icon)}${market.title}</strong><span>Dernière mise à jour ${marketDateLabel()}</span><div class="market-status-list" aria-label="État des fournisseurs">${providerRows}</div></div></div></div></section><section class="section"><span class="section-label">Calcul</span><div class="group-card settings-list"><form id="rateForm" class="settings-row"><div class="settings-copy"><strong>Conversion USD vers EUR</strong><span>Actualisée automatiquement, modifiable en secours</span></div><input name="rate" type="number" step="any" inputmode="decimal" value="${state.settings.usdToEur}"></form></div><p class="tap-caption">Validez avec la touche Entrée après modification.</p></section><section class="section"><span class="section-label">Aide</span><div class="group-card help-list"><details class="help-item" open><summary>Ajouter une cryptomonnaie</summary><div class="help-content"><p>Utilisez l’identifiant exact indiqué sur CoinGecko. Il est généralement visible dans l’adresse de la page de l’actif.</p><div class="help-example"><span>Exemples</span><code>Bitcoin → bitcoin</code><code>Solana → solana</code><code>USD Coin → usd-coin</code></div><p>Choisissez la devise USD. Après le premier enregistrement, le cours sera actualisé avec les autres cryptomonnaies.</p></div></details><details class="help-item"><summary>Ajouter un ETF ou une action</summary><div class="help-content"><p>Utilisez le symbole Yahoo Finance correspondant à la bonne place de cotation.</p><div class="help-example"><span>Exemples</span><code>EWLD Paris → EWLD.PA</code><code>Core S&amp;P 500 Xetra → SXR8.DE</code></div><p>Les suffixes comme <code>.PA</code> ou <code>.DE</code> identifient la place boursière. Vérifiez toujours l’ISIN avant d’enregistrer le symbole.</p></div></details><details class="help-item"><summary>Sources utilisées</summary><div class="help-content"><div class="help-source"><strong>CoinGecko</strong><span>Cours des cryptomonnaies et stablecoins</span></div><div class="help-source"><strong>Yahoo Finance</strong><span>Cours des ETF et actions</span></div><div class="help-source"><strong>Stooq</strong><span>Source de secours pour les ETF configurés</span></div><div class="help-source"><strong>Frankfurter</strong><span>Taux de conversion USD/EUR</span></div><p>Les positions, quantités, PRU, opérations et apports restent enregistrés uniquement sur votre appareil.</p></div></details><details class="help-item"><summary>En cas d’échec d’actualisation</summary><div class="help-content"><p>Vérifiez d’abord l’identifiant CoinGecko ou le symbole Yahoo Finance. L’application conserve le dernier cours connu et permet toujours une correction manuelle.</p></div></details></div></section><section class="section"><span class="section-label">Sauvegarde</span><div class="group-card settings-list"><div class="settings-row backup-summary-row"><div class="settings-copy"><strong>Dernière sauvegarde</strong><span>${backupDateLabel()}</span>${backupIsDue()?`<span class="backup-warning">Sauvegarde recommandée</span>`:''}</div></div><button class="list-row" id="exportBtn"><span class="row-icon backup-icon">${icon('export')}</span><span class="row-main"><strong>Exporter les données</strong><span>Positions, apports, opérations et réglages</span></span><span class="chevron">${icon('chevron')}</span></button><label class="list-row"><span class="row-icon backup-icon">${icon('import')}</span><span class="row-main"><strong>Restaurer une sauvegarde</strong><span>Aperçu avant remplacement des données</span></span><span class="chevron">${icon('chevron')}</span><input id="importInput" type="file" accept="application/json,.json" hidden></label></div><p class="tap-caption">Le fichier peut être conservé dans Fichiers, iCloud Drive ou un autre emplacement personnel.</p></section><section class="section"><span class="section-label">Données</span><div class="group-card settings-list"><div class="settings-row"><div class="settings-copy"><strong>Dernière modification</strong><span>${lastModifiedLabel()}</span></div></div><div class="settings-row"><div class="settings-copy"><strong>Contenu local</strong><span>${state.positions.length} actif${state.positions.length>1?'s':''} · ${state.assetTransactions.length} opération${state.assetTransactions.length>1?'s':''} · ${state.contributions.length} apport${state.contributions.length>1?'s':''}</span></div></div><div class="settings-row"><div class="settings-copy"><strong>Mode de stockage</strong><span>IndexedDB local · base ${esc(DB)} · schéma ${VER}</span></div></div><button class="list-row" id="resetBtn"><span class="row-icon negative">${icon('trash')}</span><span class="row-main"><strong class="negative">Réinitialiser l’application</strong><span>Restaurer la photographie et les apports initiaux</span></span><span class="chevron">${icon('chevron')}</span></button></div></section><section class="section"><span class="section-label">À propos</span><div class="group-card settings-list"><div class="settings-row"><div class="settings-copy"><strong>Patrimoine</strong><span>Version ${APP_VERSION}</span></div></div><div class="settings-row"><div class="settings-copy"><strong>Fonctionnement</strong><span>Stockage local · utilisation hors ligne · installation PWA</span></div></div><div class="settings-row"><div class="settings-copy"><strong>Sources de données</strong><span>CoinGecko, Yahoo Finance, Stooq et Frankfurter</span></div></div></div></section>`}
function referenceActions(kind,id){return `<div class="row-actions"><button class="text-button" data-edit-reference="${kind}:${esc(id)}">Modifier</button><button class="text-button danger-link" data-delete-reference="${kind}:${esc(id)}">Supprimer</button></div>`}
function referenceSettings(){const assets=state.assets.filter(x=>x.active!==false).sort((a,b)=>a.symbol.localeCompare(b.symbol)).map(a=>`<div class="operation-row"><div><strong>${esc(a.symbol)} · ${esc(a.name)}</strong><span>${esc(a.category)} · ${esc(a.currency)}${a.marketId?` · ${esc(a.marketId)}`:''}</span></div>${referenceActions('asset',a.id)}</div>`).join('')||'<div class="empty">Aucun actif.</div>',platforms=state.platforms.filter(x=>x.active!==false).sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<div class="operation-row"><div><strong>${esc(p.name)}</strong></div>${referenceActions('platform',p.id)}</div>`).join('')||'<div class="empty">Aucune plateforme.</div>';return `<section class="section"><span class="section-label">Référentiels</span><div class="group-card settings-list"><div class="settings-row"><div class="settings-copy"><strong>Actifs normalisés</strong><span>${state.assets.length} référence${state.assets.length>1?'s':''} · une référence unique par symbole et univers</span></div><button class="text-button" id="addReferenceAsset">Ajouter</button></div><div class="reference-list">${assets}</div><div class="settings-row"><div class="settings-copy"><strong>Plateformes normalisées</strong><span>${state.platforms.length} référence${state.platforms.length>1?'s':''} · réutilisées partout</span></div><button class="text-button" id="addReferencePlatform">Ajouter</button></div><div class="reference-list">${platforms}</div></div><p class="tap-caption">Renommer conserve les données et les rattache globalement au nouveau nom. Supprimer efface les données associées après confirmation.</p></section>`}
const viewMeta={dashboard:['VUE D’ENSEMBLE','Accueil'],portfolio:['PATRIMOINE','Positions'],operations:['MOUVEMENTS','Opérations'],contributions:['INVESTISSEMENTS','Apports'],settings:['APPLICATION','Réglages']};
function render(){const [over,title]=viewMeta[state.view];$('#viewOverline').textContent=over;$('#viewTitle').textContent=title;$('#app').innerHTML=state.view==='dashboard'?dashboard():state.view==='portfolio'?portfolio():state.view==='operations'?operations():state.view==='contributions'?contributions():settings()+referenceSettings();$$('.tab-bar button').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));const refresh=$('#marketRefreshBtn');if(refresh){refresh.disabled=state.marketBusy;refresh.classList.toggle('spinning',state.marketBusy);refresh.setAttribute('aria-busy',String(state.marketBusy))}bind()}
function showAsset(id){const p=livePositions().find(x=>x.id===id);if(!p)return;const tx=state.assetTransactions.filter(t=>t.positionId===id).sort((a,b)=>b.date.localeCompare(a.date)),liquid=isLiquidity(p),kind=inferredAssetType(p)==='stablecoin'?'Stablecoin':'Espèces disponibles';$('#assetDetailContent').innerHTML=`<div class="asset-sheet-head"><span class="row-icon ${liquid?'liquidity-icon':''}">${esc(p.symbol.slice(0,4))}</span><div><h2>${esc(p.name)}</h2><p>${esc(p.account)} · ${liquid?kind:esc(p.category)}</p></div></div><article class="card asset-hero ${liquid?'liquidity-hero':''}"><span class="section-label">${liquid?'Montant disponible':'Valeur actuelle'}</span><div class="asset-hero-value">${money(p.value,p.currency)}</div>${liquid?``:`<div class="performance-line ${tone(p.gain)}"><span>${p.gain>=0?'▲':'▼'}</span><span>${money(p.gain,p.currency)}</span><span>${pct(p.perf)}</span></div>`}</article><div class="card asset-stats"><div class="asset-stat"><span>Quantité</span><strong>${num.format(p.quantity)}</strong></div>${liquid?`<div class="asset-stat"><span>Devise</span><strong>${esc(p.currency)}</strong></div>`:`<div class="asset-stat"><span>PRU</span><strong>${money(p.averageCost,p.currency)}</strong></div><div class="asset-stat"><span>Cours actuel</span><strong>${money(p.currentPrice,p.currency)}</strong></div><div class="asset-stat"><span>Coût de revient</span><strong>${money(p.cost,p.currency)}</strong></div>`}</div><div class="sheet-actions"><button class="button primary wide edit-position" data-position="${p.id}">Modifier la position</button>${liquid?'':`<button class="button secondary wide edit-price" data-position="${p.id}">Modifier uniquement le cours</button>`}<button class="button secondary wide add-operation" data-position="${p.id}">Nouvelle opération</button><button class="button secondary wide close-sheet">Fermer</button></div>${tx.length?`<section class="section"><div class="section-title-row"><div><span class="section-label">Historique</span><h2>Opérations</h2></div></div><div class="group-card">${tx.map(t=>`<div class="operation-row"><div><strong>${esc({BUY:'Achat',SELL:'Vente',REWARD:'Récompense',ADJUSTMENT:'Correction'}[t.type])}</strong><span>${dateFmt.format(new Date(t.date+'T12:00:00'))}</span></div><div class="operation-amount"><strong>${num.format(t.quantity)}</strong></div></div>`).join('')}</div></section>`:''}`;$('#assetDetailDialog').showModal();$('.close-sheet').onclick=()=>$('#assetDetailDialog').close();$('.edit-position').onclick=()=>openPositionEditor(p.id);const ep=$('.edit-price');if(ep)ep.onclick=()=>openPrice(p.id);$('.add-operation').onclick=()=>{openAsset(p.id);$('#assetDetailDialog').close()}}
function openPrice(id){const p=state.positions.find(x=>x.id===id);if(!p)return;const f=$('#priceForm');f.positionId.value=p.id;f.currentPrice.value=p.currentPrice;$('#priceTitle').textContent=`${p.symbol} · ${p.name}`;$('#priceCurrency').textContent=`(${p.currency})`;$('#assetDetailDialog').close();$('#priceDialog').showModal();setTimeout(()=>f.currentPrice.select(),50)}
function openPositionEditor(id){const p=state.positions.find(x=>x.id===id);if(!p)return;fillPositionForm(p,false);$('#assetDetailDialog').close();$('#positionDialog').showModal()}
function selectOptions(items,selected,label){return items.filter(x=>x.active!==false).map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(label(x))}</option>`).join('')}
function fillPositionForm(p={},create=false){const f=$('#positionForm');f.reset();f.positionId.value=p.id||'';f.createMode.value=create?'1':'0';f.assetId.innerHTML=selectOptions(state.assets,p.assetId||'',x=>`${x.symbol} · ${x.name}`);f.platformId.innerHTML=selectOptions(state.platforms,p.platformId||'',x=>x.name);const a=state.assets.find(x=>x.id===f.assetId.value)||state.assets[0];if(!p.id&&a){f.assetId.value=a.id;f.platformId.value=state.platforms[0]?.id||''}f.assetType.value=p.assetType||a?.assetType||'investment';f.quantity.value=p.quantity??'';f.averageCost.value=p.averageCost??'';f.currentPrice.value=p.currentPrice??a?.currentPrice??'';f.openingDate.value=p.openingDate||today();f.notes.value=p.notes||'';$('#positionEditTitle').textContent=create?'Créer une position':`${p.symbol} · ${p.name}`}
