function setAssetFormType(type='BUY',positionId=''){const f=$('#assetForm');f.reset();f.date.value=today();f.positionId.innerHTML=state.positions.map(p=>`<option value="${p.id}">${esc(p.symbol)} · ${esc(p.name)} · ${esc(p.account)}</option>`).join('');f.contributionPlatformId.innerHTML=selectOptions(state.platforms,'',x=>x.name);if(positionId)f.positionId.value=positionId;f.type.value=type;const p=state.positions.find(x=>x.id===f.positionId.value);f.currency.value=p?.currency||'EUR';f.contributionPlatformId.value=p?.platformId||'';$('#assetTitle').textContent={BUY:'Enregistrer un achat',SELL:'Enregistrer une vente',REWARD:'Enregistrer un revenu',ADJUSTMENT:'Corriger une quantité'}[type]||'Nouvelle opération';syncAssetForm();}
