async function collectBackupPayload(stamp=new Date().toISOString()){
  const positions=await all('positions'),assetTransactions=await all('assetTransactions'),contributions=await all('contributions'),snapshots=await all('snapshots'),settings=Object.fromEntries((await all('settings')).filter(x=>!['previousLocalBackup','previousLocalBackupAt'].includes(x.key)).map(x=>[x.key,x.value]));
  const assets=await all('assets'),platforms=await all('platforms'),data={positions,assetTransactions,contributions,assets,platforms,snapshots};
  return {suite:'Applications personnelles',app:'Patrimoine',schemaVersion:2,appVersion:APP_VERSION,exportedAt:stamp,data,settings,format:'mon-patrimoine-backup',version:50,positions,assetTransactions,contributions,assets,platforms,snapshots};
}
async function replaceWithBackup(d){
  for(const store of ['positions','assetTransactions','contributions','assets','platforms','settings','snapshots'])await clear(store);
  for(const x of d.positions||[])await put('positions',normalizedPosition(x));
  for(const x of d.assetTransactions||[])await put('assetTransactions',x);
  for(const x of d.contributions||[])await put('contributions',x);
  for(const x of d.assets||[])await put('assets',x);
  for(const x of d.platforms||[])await put('platforms',x);
  for(const [key,value] of Object.entries(d.settings||{}))await put('settings',{key,value});
  for(const x of d.snapshots||[])await put('snapshots',x);
}
async function exportData(){
  const stamp=new Date().toISOString(),d=await collectBackupPayload(stamp);d.settings.lastBackupAt=stamp;
  const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),filename=backupFileName();
  const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
  await put('settings',{key:'lastBackupAt',value:stamp});state.settings.lastBackupAt=stamp;render();showToast('Sauvegarde exportée');
}
async function prepareImport(e){
  try{
    const file=e.target.files?.[0];if(!file)return;
    const d=validateBackup(JSON.parse(await file.text()));pendingImport=d;
    const x=backupSummary(d),date=x.date?dateTimeLabel(x.date,'Date inconnue'):'Date inconnue';
    $('#restorePreview').innerHTML=`<div class="restore-preview-card"><div><span>Fichier</span><strong>${esc(file.name)}</strong></div><div><span>Application</span><strong>${esc(d.app||'Patrimoine')}</strong></div><div><span>Date d’export</span><strong>${esc(date)}</strong></div><div><span>Positions</span><strong>${x.positions}</strong></div><div><span>Apports</span><strong>${x.contributions}</strong></div><div><span>Opérations</span><strong>${x.operations}</strong></div><div><span>Version</span><strong>${esc(x.version)}</strong></div></div><p class="form-hint">Le fichier a été vérifié. La restauration remplacera les données actuellement présentes sur cet appareil après création d’une copie locale de sécurité.</p>`;
    $('#restoreDialog').showModal();
  }catch(err){pendingImport=null;alert('Fichier invalide : '+err.message)}finally{e.target.value=''}
}
async function restorePendingImport(){
  if(!pendingImport)return;const safety=validateBackup(await collectBackupPayload());
  try{
    const d=pendingImport;await replaceWithBackup(d);
    const counts={positions:(await all('positions')).length,assetTransactions:(await all('assetTransactions')).length,contributions:(await all('contributions')).length,snapshots:(await all('snapshots')).length};
    for(const key of Object.keys(counts))if(counts[key]!==d[key].length)throw new Error(`Contrôle de cohérence impossible pour ${key}.`);
    await put('settings',{key:'previousLocalBackup',value:safety});await put('settings',{key:'previousLocalBackupAt',value:safety.exportedAt});await markLocalModification();
    pendingImport=null;$('#restoreDialog').close();await migrate();await load();showToast('Données importées');
  }catch(err){try{await replaceWithBackup(safety);await migrate();await load()}catch{}alert('Restauration impossible : '+err.message)}
}
async function resetApplication(){
  if(!confirm('Réinitialiser l’application et remplacer toutes les données actuelles ?'))return;
  const answer=prompt('Pour confirmer, saisissez EFFACER.');if(answer!=='EFFACER')return alert('Réinitialisation annulée.');
  await seed(true);await migrate();await markLocalModification();await load();showToast('Les données initiales ont été restaurées.');
}
window.addEventListener('online',()=>render());window.addEventListener('offline',()=>render());
document.addEventListener('gesturestart',e=>e.preventDefault(),{passive:false});
document.addEventListener('gesturechange',e=>e.preventDefault(),{passive:false});
document.addEventListener('dblclick',e=>{if(!e.target.closest('input,textarea,select'))e.preventDefault()},{passive:false});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;$('#installBtn').classList.remove('hidden')});$('#installBtn').onclick=async()=>{if(deferredPrompt){deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null}};
(async()=>{try{db=await openDB();await seed();await migrate();await load();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js?v=40');if(state.settings.autoMarketUpdate!==false&&navigator.onLine)setTimeout(()=>updateMarketPrices({silent:true}),400)}catch(e){$('#app').innerHTML=`<div class="card note negative">Erreur : ${esc(e.message)}</div>`}})();
